package dev.veltraph.client.inventory.selling;
import dev.veltraph.client.game.GameArea;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class GeorgeWarpPermitTest {
    final UUID uuid=UUID.fromString("00000000-0000-0000-0000-000000000001");final Object player=new Object(),originWorld=new Object(),hubWorld=new Object(),connection=new Object();final Vec3 hub=new Vec3(10,70,20);
    GeorgeWarpPermit.Observation o(Object p,Object w,Object c,long serial,Vec3 teleport,long tick,GameArea area,boolean loaded){return new GeorgeWarpPermit.Observation(uuid,p,w,c,area,"minecraft:overworld",area==GameArea.HUB?hub:new Vec3(0,70,0),true,loaded,true,serial,teleport,tick);}
    GeorgeWarpPermit issue(){return GeorgeWarpPermit.issue(o(player,originWorld,connection,3,null,0,GameArea.GARDEN,true),new GeorgeWarpPermit.Destination(GameArea.HUB,"minecraft:overworld",hub,.35),80);}
    @Test void sourceWarpOneUseRequiresNewerNativeSignalAndExactArrival(){var permit=issue();assertFalse(permit.observe(o(player,originWorld,connection,3,hub,1,GameArea.HUB,true)));var nativeHub=o(new Object(),hubWorld,connection,4,hub,2,GameArea.HUB,true);assertTrue(permit.observe(nativeHub));assertTrue(permit.consumeExpectedTeleport(hub,2));assertFalse(permit.consumeExpectedTeleport(hub,2));assertTrue(permit.commit(nativeHub).isPresent());assertEquals(permit.pending(),permit.cachedPendingNativeWarp().orElseThrow());assertTrue(permit.commit(nativeHub).isEmpty());}
    @Test void connectionDestinationSupportUnknownOrReplacedReceiptReject(){for(int n=0;n<3;n++){var permit=issue();var received=o(new Object(),hubWorld,n==0?new Object():connection,4,n==1?new Vec3(50,70,20):hub,2,n==2?GameArea.GARDEN:GameArea.HUB,true);assertFalse(permit.observe(received));assertEquals(GeorgeWarpPermit.State.CANCELLED,permit.state());}}
    @Test void unknownLoadingAndUnsupportedArrivalHoldExactReceiptUntilReady(){var permit=issue();var destinationPlayer=new Object();
        var loading=new GeorgeWarpPermit.Observation(uuid,destinationPlayer,hubWorld,connection,GameArea.UNKNOWN,"minecraft:overworld",hub,true,false,false,4,hub,1,true);
        assertFalse(permit.observe(loading));assertEquals(GeorgeWarpPermit.State.WAITING,permit.state());assertEquals(4,permit.cachedNativeReceipt().orElseThrow().nativeSerial());assertTrue(permit.cachedPendingNativeWarp().isPresent());assertFalse(permit.consumeExpectedTeleport(hub,1));
        var unknown=new GeorgeWarpPermit.Observation(uuid,destinationPlayer,hubWorld,connection,GameArea.UNKNOWN,"minecraft:overworld",hub,true,true,true,4,hub,2);
        assertFalse(permit.observe(unknown));assertEquals(GeorgeWarpPermit.State.WAITING,permit.state());
        var unsupported=new GeorgeWarpPermit.Observation(uuid,destinationPlayer,hubWorld,connection,GameArea.HUB,"minecraft:overworld",hub,true,true,false,4,hub,3);
        assertFalse(permit.observe(unsupported));assertEquals(GeorgeWarpPermit.State.WAITING,permit.state());
        var ready=o(destinationPlayer,hubWorld,connection,4,hub,4,GameArea.HUB,true);assertTrue(permit.observe(ready));assertTrue(permit.commit(ready).isPresent());assertTrue(permit.cachedPendingNativeWarp().isPresent());}
    @Test void loadingWithoutNativeReceiptCannotGrantAdmissionAndExpires(){var permit=issue();var loading=new GeorgeWarpPermit.Observation(uuid,null,null,connection,GameArea.UNKNOWN,"",hub,false,false,false,3,null,1,true);assertFalse(permit.observe(loading));assertEquals(GeorgeWarpPermit.State.WAITING,permit.state());assertTrue(permit.cachedNativeReceipt().isEmpty());var late=new GeorgeWarpPermit.Observation(uuid,null,null,connection,GameArea.UNKNOWN,"",hub,false,false,false,3,null,80,true);assertFalse(permit.observe(late));assertEquals(GeorgeWarpPermit.State.CANCELLED,permit.state());}
    @Test void cachedLoadingReceiptCannotChangeSerialPositionWorldOrConnection(){for(int mode=0;mode<4;mode++){var permit=issue();var p=new Object();assertFalse(permit.observe(new GeorgeWarpPermit.Observation(uuid,p,hubWorld,connection,GameArea.UNKNOWN,"minecraft:overworld",hub,true,false,false,4,hub,1,true)));var changed=new GeorgeWarpPermit.Observation(uuid,p,mode==0?new Object():hubWorld,mode==1?new Object():connection,GameArea.HUB,"minecraft:overworld",hub,true,true,true,mode==2?5:4,mode==3?new Vec3(10.1,70,20):hub,2);assertFalse(permit.observe(changed));assertEquals(GeorgeWarpPermit.State.CANCELLED,permit.state());}}
    @Test void knownWrongDimensionUuidAndHealthNeverUseLoadingHold(){for(int mode=0;mode<3;mode++){var permit=issue();var wrong=new GeorgeWarpPermit.Observation(mode==0?UUID.randomUUID():uuid,new Object(),hubWorld,connection,GameArea.HUB,mode==1?"minecraft:the_nether":"minecraft:overworld",hub,mode!=2,true,true,4,hub,1);assertFalse(permit.observe(wrong));assertEquals(GeorgeWarpPermit.State.CANCELLED,permit.state());}}
    @Test void lateCancelledAndChangedWorldCommitCannotGrantAdmission(){var permit=issue();var nativeHub=o(new Object(),hubWorld,connection,4,hub,2,GameArea.HUB,true);assertTrue(permit.observe(nativeHub));assertTrue(permit.commit(o(nativeHub.player(),new Object(),connection,4,hub,3,GameArea.HUB,true)).isEmpty());var cancelled=issue();cancelled.cancel();assertFalse(cancelled.observe(nativeHub));var timed=issue();assertFalse(timed.observe(o(player,hubWorld,connection,4,hub,80,GameArea.HUB,true)));}
}
